# -*- coding: utf-8 -*-
"""
crosstext_kavya_write.py  — assemble the CURATED kāvya cross-text notes.

Method: SLP1 content-stem intersection (Sundarakāṇḍa x kāvya cluster
[Raghuvaṃśa, Kumārasambhava, Meghadūta, Buddhacarita, Gītagovinda,
Śatakatraya]) on RARE shared stems -> locate the real parallel verse in the
source -> human judgement of genuine illumination (locus classicus / shared
epithet-formula of a comparable figure / gnomic parallel / kāvya reworking /
mythological background). Coincidental overlaps skipped.

Each note quotes the parallel (IAST + Russian) in note_ru.
type: А = ходячая формула/гномическая максима/общий эпитет
      Б = locus classicus термина / технический смысл
      В = кавья-переработка мотива / мифологический фон

Writes data/crosstext/kavya.json (UTF-8, no BOM). Never touches Leonov.
"""
import sys, json
from pathlib import Path
from datetime import date

sys.stdout.reconfigure(encoding='utf-8')
sys.stderr.reconfigure(encoding='utf-8')

ROOT = Path(r"C:\Users\user\Documents\GitHub\CommentaryStrategies-crosstext")
OUT  = ROOT / "data" / "crosstext" / "kavya.json"
OUT.parent.mkdir(parents=True, exist_ok=True)

def note(shloka, lemma, type_, source, stem, addr, text):
    return {
        "shloka": shloka,
        "lemma_iast": lemma,
        "note_ru": text.strip(),
        "type": type_,
        "trigger": "crosstext",
        "subtype": "cross_text",
        "source": source,
        "stem": stem,
        "parallel_addr": addr,
        "cluster": "kavya",
        "review_required": True,
    }

NOTES = []
A = NOTES.append

